output_text:
[
  {
    "id": "must_checkout_cart",
    "text": "A customer is obliged to pick up the entrance cart at the cart station before leaving the store.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_station": "at(1,5)",
        "cart_available_at_entrance": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_station",
              "cart_available_at_entrance",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "no_item_without_cart",
    "text": "A customer is forbidden to pick up shelf items unless they are currently using a cart.",
    "abstraction": {
      "state_properties": {
        "using_cart": "hasCart"
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "return_checked_out_cart",
    "text": "Once a customer has checked out a cart, they are obliged to return it to the front cart-return point.",
    "abstraction": {
      "state_properties": {
        "front_cart_return_point": "at(0,1)",
        "cart_parked_at_front": "cartAt(0,1)"
      },
      "events": {
        "take_cart": {
          "pre": {
            "and": [
              "PICKUP_CART",
              "hasCart"
            ]
          },
          "post": "hasCart"
        },
        "return_cart_to_front": {
          "pre": {
            "and": [
              "front_cart_return_point",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_at_front"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_cart",
      "discharge": "return_cart_to_front"
    }
  },
  {
    "id": "park_only_at_front",
    "text": "A customer is forbidden to leave a cart anywhere except the designated front return point at (0,1).",
    "abstraction": {
      "state_properties": {
        "front_cart_return_point": "at(0,1)"
      },
      "events": {
        "leave_cart_outside_return": {
          "pre": {
            "and": [
              "LEAVE_CART",
              {
                "not": "front_cart_return_point"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_outside_return"
    }
  },
  {
    "id": "exit_only_after_cart_return",
    "text": "A customer is forbidden to exit while still holding the cart or while the cart is not parked at the front return point.",
    "abstraction": {
      "state_properties": {
        "cart_returned": "cartAt(0,1)"
      },
      "events": {
        "improper_exit_with_cart_unreturned": {
          "pre": {
            "and": [
              "EXIT",
              {
                "or": [
                  "hasCart",
                  {
                    "not": "cart_returned"
                  }
                ]
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "improper_exit_with_cart_unreturned"
    }
  },
  {
    "id": "cart_free_exit_side",
    "text": "Shopping carts are forbidden in the eastern exit-side area of the store.",
    "abstraction": {
      "state_properties": {
        "east_exit_side_area": {
          "or": [
            "at(7,0)",
            "at(7,1)",
            "at(7,2)",
            "at(7,3)",
            "at(7,4)",
            "at(7,5)",
            "at(8,0)",
            "at(8,1)",
            "at(8,2)",
            "at(8,3)",
            "at(8,4)",
            "at(8,5)",
            "at(9,0)",
            "at(9,1)",
            "at(9,2)",
            "at(9,3)",
            "at(9,4)",
            "at(9,5)"
          ]
        },
        "using_cart": "hasCart"
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "using_cart",
          "east_exit_side_area"
        ]
      }
    }
  },
  {
    "id": "turn_back_from_egg_end",
    "text": "After picking up an item at the east end shelf at (6,4), a cart user is obliged to turn back west rather than continue east.",
    "abstraction": {
      "state_properties": {
        "egg_end_shelf_position": "at(6,4)",
        "using_cart": "hasCart"
      },
      "events": {
        "pickup_at_east_end_shelf": {
          "pre": {
            "and": [
              "egg_end_shelf_position",
              "using_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": "using_cart"
        },
        "west_from_east_end_shelf_with_cart": {
          "pre": {
            "and": [
              "egg_end_shelf_position",
              "using_cart",
              "W"
            ]
          },
          "post": "at(5,4)"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "pickup_at_east_end_shelf",
      "discharge": "west_from_east_end_shelf_with_cart"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "Customers are forbidden to carry items loose by hand; collected items should be transported in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "using_cart": "hasCart"
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "and": [
              {
                "not": "carrying_item_by_hand"
              },
              "PICKUP_ITEM",
              {
                "not": "using_cart"
              }
            ]
          },
          "post": "carrying_item_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  }
]
